def parse_pairs(lines):
    result = {}
    for line in lines:
        if not line.strip():
            continue
        if '=' not in line:
            raise ValueError("missing '=' in line: %r" % line)
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError("empty key in line: %r" % line)
        result[key] = value
    return result

